function n(){document.querySelectorAll('input[type="file"]').forEach(e=>{if(e.dataset.editorAttached)return;e.dataset.editorAttached="true",e.addEventListener("change",t=>{if(e.dataset.editorApplying==="true"){delete e.dataset.editorApplying;return}const o=t.target.files?.[0];if(!o||!o.type.startsWith("image/")||typeof window.openEditor!="function")return;t.preventDefault();const r=new FileReader;r.onload=()=>window.openEditor(r.result,e,o),r.readAsDataURL(o)})})}
chrome.runtime.onMessage.addListener(e=>{e?.type==="OPEN_EDITOR_FROM_CONTEXT"&&typeof window.openEditorFromContext==="function"&&window.openEditorFromContext(e.imageSrc)});
const a=new MutationObserver(()=>n());a.observe(document.body,{childList:!0,subtree:!0});n();
